   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1120;
       --panel: rgba(15, 23, 42, 0.92);
       --panel-border: rgba(148, 163, 184, 0.22);
       --text: #e5e7eb;
       --muted: #94a3b8;
       --accent: #8b5cf6;
       --accent-strong: #7c3aed;
       --accent-soft: rgba(139, 92, 246, 0.18);
       --shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
     }

     * {
       box-sizing: border-box;
     }

