       place-items: center;
       padding: 24px;
       font-family: Arial, Helvetica, sans-serif;
       background:
         radial-gradient(circle at top, rgba(139, 92, 246, 0.2), transparent 32%),
         linear-gradient(160deg, #020617 0%, #0f172a 50%, #111827 100%);
       color: var(--text);
     }

     .card {
       width: min(100%, 520px);
       padding: 32px;
       border: 1px solid var(--panel-border);
       border-radius: 20px;
       background: var(--panel);
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
     }

     h1 {
       margin: 0 0 10px;
       font-size: 1.8rem;
