   <main class="card">
     <h1>Notification Preferences</h1>
     <p class="intro">Choose how you would like to receive updates so we can contact you the right way.</p>

     <form id="notification-form">
       <div class="form-field">
         <fieldset>
           <legend>How do you prefer to receive notifications?</legend>
           <div class="options">
             <label class="option" for="notify-email">
               <input id="notify-email" type="radio" name="notificationPreference" value="Email" required>
               <span class="option-text">Email</span>
             </label>

