               <span class="option-text">SMS</span>
             </label>

             <label class="option" for="notify-push">
               <input id="notify-push" type="radio" name="notificationPreference" value="Push Notifications">
               <span class="option-text">Push Notifications</span>
             </label>
           </div>
         </fieldset>
       </div>

       <button type="submit">Submit</button>
       <p class="message" id="form-message" aria-live="polite"></p>
